-- Both gates must be true. Do not replay historical migrations.
SELECT ((EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261027000000' AND name='course_topic_content' AND cardinality(statements)=1 AND md5(statements[1])='fcec56f3aa75dae989c9b8dd4afb9ab2') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261028000000' AND name='course_topic_practice' AND cardinality(statements)=1 AND md5(statements[1])='f8d0fd626747b1dd42fd6f03cf285591') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261029000000' AND name='course_html_games' AND cardinality(statements)=1 AND md5(statements[1])='e895306287717adabf7e04da5c46b1d8') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261030000000' AND name='course_legacy_links' AND cardinality(statements)=1 AND md5(statements[1])='a2276460fd2247c87bb072bee8defac3')) AND (coalesce((SELECT md5(prosrc)='1f84e00c07b216e3635bd1531eb18c5f' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.course_topic_visible(uuid,uuid)')),false) AND coalesce((SELECT md5(prosrc)='3d6c6579b69b6a3f66821982946f2a16' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_course_outline(uuid)')),false) AND coalesce((SELECT md5(prosrc)='2e37ea29641f3b34e50ff69c642cd773' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_course_topic(uuid,uuid)')),false) AND coalesce((SELECT md5(prosrc)='0a4d7a055519f528e6c64fb949364698' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.save_course_topic(uuid,uuid,boolean,jsonb,text)')),false) AND coalesce((SELECT md5(prosrc)='9aed4a1fe4b81f05771f66c3fea8ab3a' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.guard_published_course_video()')),false) AND coalesce((SELECT md5(prosrc)='84c2812e270a0c99f1281f5d99d971e7' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.resolve_course_video(uuid)')),false)) AND to_regclass('public.course_topic_content') IS NOT NULL AND to_regclass('storage.objects') IS NOT NULL) AS prerequisites_match,(NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261031000000') AND to_regclass('public.course_lessons') IS NULL AND to_regclass('public.course_lesson_courses') IS NULL AND to_regclass('public.course_lesson_videos') IS NULL) AS new_migration_absent;
SELECT id,title,practice_course_scope,is_published FROM public.courses ORDER BY title;
SELECT c.title,t.topic_code,l.is_published,l.game_path,count(v.video_id) AS video_count FROM public.course_topic_content l JOIN public.courses c ON c.id=l.course_id JOIN public.curriculum_topics t ON t.id=l.topic_id LEFT JOIN public.course_topic_videos v ON v.course_id=l.course_id AND v.topic_id=l.topic_id GROUP BY c.title,t.topic_code,l.is_published,l.game_path ORDER BY t.topic_code,c.title;
